    private static int reverseBits(int n, int k) {
        int result = 0;
        for (int i = 0; i < k; i++) {
            result = (result << 1) | (n & 1);
            n >>= 1;
        }
        return result;
    }

    private static long fastPow(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modularInverse(long a) {
        return fastPow(a, MOD - 2);
    }

    private static long[] computeRoots(int k, boolean inverse) {
        long root = fastPow(ROOT, fastPow(2, twoPow - k));
        if (inverse) {
            root = modularInverse(root);
        }
        long[] roots = new long[k];
        if (k > 0) {
            roots[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
