#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int twoPow = 23;
const int ROOT = 15311432;

int reverseBits(int n, int k) {
    int result = 0;
    for (int i = 0; i < k; i++) {
        result = (result << 1) | (n & 1);
        n >>= 1;
    }
    return result;
}

long long fastPow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modularInverse(long long a) {
    return fastPow(a, MOD - 2);
}

vector<long long> computeRoots(int k, bool inverse) {
    long long root = fastPow(ROOT, fastPow(2, twoPow - k));
    if (inverse) {
        root = modularInverse(root);
    }
    vector<long long> roots(k);
    if (k > 0) {
        roots[k - 1] = root;
    }
    for (int i = k - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    return roots;
}

vector<long long> reorder(const vector<long long>& array, int k) {
    int n = array.size();
    vector<long long> result(n);
    for (int i = 0; i < n; i++) {
        result[reverseBits(i, k)] = array[i];
    }
    return result;
}

vector<long long> nttTransform(vector<long long> coef, int k, bool inverse) {
    coef = reorder(coef, k);
    vector<long long> roots = computeRoots(k, inverse);
    for (int s = 0; s < k; s++) {
        int segmentLength = 1 << s;
        for (int start = 0; start < (int)coef.size(); start += 2 * segmentLength) {
            long long currentRoot = 1;
            for (int j = start; j < start + segmentLength; j++) {
                long long t = (currentRoot * coef[j + segmentLength]) % MOD;
                long long u = coef[j];
                coef[j] = (u + t) % MOD;
                coef[j + segmentLength] = (u - t + MOD) % MOD;
                currentRoot = (roots[s] * currentRoot) % MOD;
            }
        }
    }
    return coef;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    int maxVal = 0;
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
        maxVal = max(maxVal, nums[i]);
    }
    int minSize = n * maxVal + 1;
    int size = 1, k = 0;
    while (size < minSize) {
        size <<= 1;
        k++;
    }
    vector<long long> array(size, 0);
    for (int val : nums) {
        array[val] = 1;
    }
    array = nttTransform(array, k, false);
    for (int i = 0; i < size; i++) {
        array[i] = fastPow(array[i], n);
    }
    array = nttTransform(array, k, true);
    long long total = 0;
    for (int i = 0; i < size; i++) {
        total = (total + array[i] * array[i]) % MOD;
    }
    long long invSize = modularInverse(size);
    cout << (((total * invSize) % MOD) * invSize) % MOD << "\n";
    return 0;
}
